  const reference = authz.compositeResources.define(libraryDocuments);
  authz.ui.sections.add({
    name: 'library',
    title: { key: 'library.navigation', ns: 'nb3-factory' },
    parent: 'business',
  });
  authz.ui.place(reference, { section: 'library' });

  authz.ui.sections.add({
    name: 'library.admin',
    title: { key: 'library.navigation', ns: 'nb3-factory' },
    parent: 'administration',
